#!/usr/bin/env node

// External-only verifier. Frozen A5 text and local paths are injected by CLI and
// never copied into this repository. The manifest is an independent oracle and
// is never regenerated by this tool.
import { createHash } from 'node:crypto';
import { mkdtemp, readFile, realpath, rm, writeFile } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { dirname, isAbsolute, join, resolve } from 'node:path';
import { createRequire } from 'node:module';
import { fileURLToPath, pathToFileURL } from 'node:url';
import { generateResolvedCaptionOverlays } from '../../render-cut/src/captions.mjs';
import { resolveCaptionApiPayload } from '../../preview-server/src/caption-api.mjs';

const require = createRequire(import.meta.url);
const repositoryRoot = resolve(dirname(fileURLToPath(import.meta.url)), '../../..');
const { resolveCaptionDisplay } = require('../lib/index.js');
const { projectRoot: projectArg, manifest: manifestArg } = parseArguments(process.argv.slice(2));
if (!projectArg || !manifestArg) {
  console.error('Usage: node packages/edit-store/tools/verify-a4-caption-golden.mjs --project-root <path> --manifest <manifest.json>');
  process.exit(2);
}

try {
  const projectRoot = await realpath(resolve(projectArg));
  const manifest = JSON.parse(await readFile(resolve(manifestArg), 'utf8'));
  if (manifest.version !== 1 || manifest.projection?.schema !== 'akari-caption-display-golden-row/v1') throw new Error('unsupported golden manifest');
  for (const input of manifest.frozen_project?.inputs ?? []) {
    if (!safeRelative(input.path) || !/^[a-f0-9]{64}$/u.test(input.sha256)) throw new Error('manifest has an unsafe input row');
    if (sha256(await readFile(join(projectRoot, input.path))) !== input.sha256) throw new Error(`frozen input SHA mismatch: ${input.path}`);
  }
  const edit = JSON.parse(await readFile(join(projectRoot, 'edit.json'), 'utf8'));
  const captionsRoot = JSON.parse(await readFile(join(projectRoot, 'captions.json'), 'utf8'));
  const overrides = JSON.parse(await readFile(join(projectRoot, '.akari/provenance/caption-line-overrides.a4.json'), 'utf8')).overrides ?? {};
  const root = {
    ...captionsRoot,
    display_policy: manifest.algorithm_inputs,
    default_text_style: manifest.style_algorithm_input?.default_text_style,
    captions: captionsRoot.captions.map(caption => ({
      ...caption,
      ...(Object.hasOwn(overrides, caption.id) ? { display_fragments: overrides[caption.id] } : {}),
    })),
  };
  if (!root.default_text_style) throw new Error('style_algorithm_input.default_text_style is required');
  const result = resolveCaptionDisplay(root, edit);
  const renderCues = generateResolvedCaptionOverlays(result).map(overlay => overlay.displayCue);
  const previewCues = resolveCaptionApiPayload(root, edit).captions;
  const shellCues = await resolveThroughShellBackend({ projectRoot, captionsRoot: root });
  if (JSON.stringify(renderCues) !== JSON.stringify(result.display_cues)) throw new Error('render consumer display cues differ from kernel');
  if (JSON.stringify(previewCues) !== JSON.stringify(result.display_cues)) throw new Error('preview consumer display cues differ from kernel');
  if (JSON.stringify(shellCues) !== JSON.stringify(result.display_cues)) throw new Error('shell consumer display cues differ from kernel');
  const rows = result.display_cues.map(cue => ({
    id: cue.id,
    source_cue_id: cue.source_cue_id,
    src: cue.src,
    cut_index: cue.cut_index,
    occurrence_index: cue.occurrence_index,
    fragment_index: cue.fragment_index,
    fragment_count: cue.fragment_count,
    start: cue.start,
    end: cue.end,
    text: cue.text,
    units: cue.units,
    line_override: cue.line_override,
  }));
  const canonical = JSON.stringify(rows);
  const consumerSha256 = Object.fromEntries([
    ['kernel', result.display_cues],
    ['render', renderCues],
    ['preview', previewCues],
    ['shell', shellCues],
  ].map(([name, cues]) => [name, sha256(JSON.stringify(cues.map(cue => ({
    id: cue.id,
    source_cue_id: cue.source_cue_id,
    src: cue.src,
    cut_index: cue.cut_index,
    occurrence_index: cue.occurrence_index,
    fragment_index: cue.fragment_index,
    fragment_count: cue.fragment_count,
    start: cue.start,
    end: cue.end,
    text: cue.text,
    units: cue.units,
    line_override: cue.line_override,
  }))))]));
  if (new Set(Object.values(consumerSha256)).size !== 1) throw new Error('consumer projection SHA mismatch');
  const checks = {
    source_cue_count: result.source_cue_count,
    occurrence_count: result.occurrence_count,
    display_cue_count: result.display_cue_count,
    split_source_cue_count: result.split_source_cue_count,
    canonical_bytes: Buffer.byteLength(canonical),
    expected_sha256: sha256(canonical),
  };
  for (const [key, value] of Object.entries(checks)) {
    if (manifest.projection[key] !== value) throw new Error(`projection ${key} mismatch: expected ${manifest.projection[key]}, got ${value}`);
  }
  const boundaryCanonical = JSON.stringify(result.boundary_projection);
  const geometryParity = verifyGeometryOracle(
    manifest.geometry_oracle,
    manifest.style_algorithm_input,
    result.display_cues,
  );
  console.log(JSON.stringify({
    verdict: 'PASS',
    ...checks,
    runtime: { node: process.version, icu: process.versions.icu ?? null },
    consumer_sha256: consumerSha256,
    geometry_parity: geometryParity,
    boundary_projection_sha256: sha256(boundaryCanonical),
  }, null, 2));
} catch (error) {
  console.error(`A4 caption golden verification failed: ${error instanceof Error ? error.message : String(error)}`);
  process.exit(1);
}

async function resolveThroughShellBackend({ projectRoot, captionsRoot }) {
  const shellModule = process.env.AKARI_SHELL_SERVICE_MODULE
    ? resolve(process.env.AKARI_SHELL_SERVICE_MODULE)
    : join(repositoryRoot, 'apps/shell/extensions/akari-preview/lib/node/akari-preview-service.js');
  let AkariPreviewServiceImpl;
  try {
    ({ AkariPreviewServiceImpl } = require(shellModule));
  } catch (error) {
    throw new Error(`shell backend is unavailable; build akari-preview before golden verification: ${error instanceof Error ? error.message : String(error)}`);
  }
  const temporary = await mkdtemp(join(tmpdir(), 'akari-a5-shell-consumer-'));
  try {
    const captionsPath = join(temporary, 'captions.json');
    const workspacePath = join(temporary, 'a5-shell-consumer.code-workspace');
    await writeFile(captionsPath, JSON.stringify(captionsRoot));
    await writeFile(workspacePath, JSON.stringify({ folders: [
      { path: pathToFileURL(projectRoot).toString() },
      { path: pathToFileURL(temporary).toString() },
    ] }));
    const service = new AkariPreviewServiceImpl();
    service.workspaceServer = {
      getMostRecentlyUsedWorkspace: async () => pathToFileURL(workspacePath).toString(),
    };
    const payload = await service.resolveCaptionDisplay({
      captionsUri: pathToFileURL(captionsPath).toString(),
      editUri: pathToFileURL(join(projectRoot, 'edit.json')).toString(),
    });
    if (!payload || !Array.isArray(payload.captions)) throw new Error('shell backend did not return resolved captions');
    return payload.captions;
  } finally {
    await rm(temporary, { recursive: true, force: true });
  }
}

function verifyGeometryOracle(oracle, styleAlgorithmInput, cues) {
  if (!oracle || oracle.output?.width_px !== 1920 || oracle.output?.height_px !== 1080 || !oracle.resolved_style) {
    throw new Error('geometry_oracle is missing or unsupported');
  }
  const expected = oracle.resolved_style;
  const scales = new Set();
  for (const cue of cues) {
    const vars = cue.style_vars ?? {};
    const layout = cue.layout ?? {};
    if (layout.reference_width_px !== oracle.output.width_px
        || layout.reference_height_px !== oracle.output.height_px
        || !(Number.isFinite(layout.scale) && layout.scale > 0)) {
      throw new Error('geometry_oracle reference dimensions or output scale mismatch');
    }
    const scale = layout.scale;
    scales.add(scale);
    const checks = {
      color: vars['--caption-color'],
      size_px: cssPixels(vars['--caption-font-size']) / scale,
      font_weight: Number(vars['--caption-font-weight']),
      line_height: Number(vars['--caption-line-height']),
      stroke_method: vars['--caption-webkit-text-stroke'] ? 'webkit-outline' : null,
      stroke_color: String(vars['--caption-webkit-text-stroke'] ?? '').split(' ').at(-1),
      stroke_width_px: cssPixels(String(vars['--caption-webkit-text-stroke'] ?? '').split(' ')[0]) / scale,
      plate_left_px: layout.left_px / scale,
      plate_width_px: layout.width_px / scale,
      plate_right_px: layout.right_px / scale,
      plate_center_x_px: layout.center_x_px / scale,
      plate_bottom_px: layout.bottom_px / scale,
      text_align: layout.text_align,
      max_lines: layout.max_lines,
    };
    for (const [key, value] of Object.entries(checks)) {
      if (value !== expected[key]) throw new Error(`geometry_oracle ${key} mismatch: expected ${expected[key]}, got ${value}`);
    }
    if (vars['--caption-paint-order'] !== 'stroke fill' || vars['--caption-text-shadow'] !== 'none') {
      throw new Error('geometry_oracle outline variables are incomplete');
    }
  }
  if (scales.size !== 1) throw new Error('geometry_oracle output scale varies between cues');
  return {
    oracle_source: oracle.source,
    oracle_sha256: sha256(JSON.stringify(oracle)),
    style_algorithm_input_source: 'manifest#style_algorithm_input.default_text_style',
    style_algorithm_input_sha256: sha256(JSON.stringify(styleAlgorithmInput)),
    output_scale_from_reference: [...scales][0],
    resolved_cue_count: cues.length,
    style_vars_sha256: sha256(JSON.stringify(cues.map(cue => cue.style_vars))),
    visual_test: 'packages/preview-server/test/caption-visual-parity.test.mjs',
  };
}

function cssPixels(value) {
  const match = /^(-?(?:\d+\.?\d*|\.\d+))px$/u.exec(String(value));
  return match ? Number(match[1]) : Number.NaN;
}

function safeRelative(value) {
  return typeof value === 'string' && value !== '' && !isAbsolute(value) && !value.split(/[\\/]/u).includes('..');
}

function parseArguments(args) {
  if (args.length === 2 && args.every(value => !value.startsWith('--'))) {
    return { projectRoot: args[0], manifest: args[1] };
  }
  const parsed = { projectRoot: null, manifest: null };
  for (let index = 0; index < args.length; index += 1) {
    const argument = args[index];
    if (argument === '--project-root' && index + 1 < args.length) parsed.projectRoot = args[++index];
    else if (argument === '--manifest' && index + 1 < args.length) parsed.manifest = args[++index];
    else return { projectRoot: null, manifest: null };
  }
  return parsed;
}

function sha256(value) {
  return createHash('sha256').update(value).digest('hex');
}
